# ============================================================
#  Planned Ltd - one-click blog publisher
#  Publishes 3 posts: Resource Levelling, AMP8 Water, Rail/CP7
#  Run in PowerShell:
#    $b=@("$env:ProgramFiles\Git\bin\bash.exe","${env:ProgramFiles(x86)}\Git\bin\bash.exe","$env:LOCALAPPDATA\Programs\Git\bin\bash.exe")|?{Test-Path $_}|select -First 1; & $b publish-3-sector-posts.sh
# ============================================================
set -e
cd "$HOME/Documents/planned-website"
git config user.name "Akin Akindele"
git config user.email "akin.akindele11@gmail.com"

echo ">> Bringing your local copy up to date with the live site..."
git fetch origin
git reset --hard origin/main

echo ">> Writing the 3 posts and the updated index/sitemap/llms files..."
mkdir -p blog
base64 -d > "blog/p6-resource-levelling-best-practices.html" <<'B64_LEVEL'
